contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint depositAmount, uint collectAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmount)); require(depositAmount <= 1000000000000000000000000000000);
        require(depositAmount >= 1 ether, "deposit below MinSum");
        require(collectAmount <= depositAmount, "collect exceeds deposit");
        require(address(this).balance >= depositAmount, "not enough balance");

        c.Deposit{value: depositAmount}(); if (__ESBMC_reverted()) return;

        uint minSum = c.MinSum(); if (__ESBMC_reverted()) return;
        uint beforeBalance = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint beforeCBalance = address(c).balance;
        uint beforeContractBalance = address(this).balance;

        bool reverted;
        c.Collect(collectAmount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint afterBalance = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint afterCBalance = address(c).balance;
        uint afterContractBalance = address(this).balance;

        assert(
            reverted || (
                beforeBalance >= minSum &&
                beforeBalance >= collectAmount &&
                afterBalance == beforeBalance - collectAmount &&
                afterCBalance == beforeCBalance - collectAmount &&
                afterContractBalance == beforeContractBalance + collectAmount
            )
        );
    }

    receive() external payable {}
}

